/**
 * "What is your health plan or employer?" modal shown after choosing to
 * explore MyPrime without signing in. Some plans (e.g. BCBS Alabama) show a
 * second required "Medicare Part D" dropdown; others don't, so callers should
 * check {@link #isMedicarePartDPromptDisplayed()} before interacting with it.
 */
import { BasePage } from './base-page.js';
import { HomePage } from './home-page.js';

export class PlanSelectorModal extends BasePage {
  /** @param {import('@playwright/test').Page} page */
  constructor(page) {
    super(page);
    // .first(): Selenium By-locators resolve to the first match; the AUT even
    // ships duplicate ids, so keep that semantic instead of strict mode.
    this.healthPlanDropdown = page.locator("#cwsi-plan").first();
    this.medicarePartDDropdown = page.locator("#cwsi-medicare-d").first();
    this.continueButton = page.locator("#plan-selector-form button.button-primary").first();
  }

  async selectHealthPlan(planName) {
    await this.selectOptionWhenPopulated(this.healthPlanDropdown, planName);
    return this;
  }

  async isMedicarePartDPromptDisplayed() {
    return await this.isVisibleWithin(this.medicarePartDDropdown, 3000);
  }

  async selectMedicarePartD(yesNo) {
    await this.selectOptionWhenPopulated(this.medicarePartDDropdown, yesNo);
    return this;
  }

  /**
   * Selects the plan, answers the Medicare Part D prompt when the chosen plan
   * requires it, then submits. Lands back on the (now plan-scoped) home page.
   */
  async selectPlanAndContinue(planName, medicarePartDAnswer) {
    await this.selectHealthPlan(planName);
    if (await this.isMedicarePartDPromptDisplayed()) {
      await this.selectMedicarePartD(medicarePartDAnswer);
    }
    await this.continueButton.click();
    return new HomePage(this.page);
  }
}
